package pe.greenminds.ecomind.community.infrastructure.persistence.jpa.adapters;
import java.util.List;import java.util.Optional;import org.springframework.stereotype.Repository;import pe.greenminds.ecomind.community.domain.model.aggregates.Post;import pe.greenminds.ecomind.community.domain.repositories.PostRepository;import pe.greenminds.ecomind.community.infrastructure.persistence.jpa.assemblers.PostPersistenceAssembler;import pe.greenminds.ecomind.community.infrastructure.persistence.jpa.repositories.PostPersistenceRepository;
@Repository public class PostRepositoryImpl implements PostRepository{private final PostPersistenceRepository repository;public PostRepositoryImpl(PostPersistenceRepository r){repository=r;}public Post save(Post p){return PostPersistenceAssembler.toDomain(repository.save(PostPersistenceAssembler.toEntity(p)));}public Optional<Post> findById(Long id){return repository.findById(id).map(PostPersistenceAssembler::toDomain);}public List<Post> findAll(Long c){return (c==null?repository.findAll():repository.findByCommunityIdOrderByCreatedAtDesc(c)).stream().map(PostPersistenceAssembler::toDomain).toList();}public void delete(Post p){repository.deleteById(p.id());}public boolean existsById(Long id){return repository.existsById(id);}}
